const lessons=[{"sentences":[{"speaker":"A","text":"We should check the weather forecast before packing our picnic basket today.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.889},{"speaker":"B","text":"The wind outside looks extremely strong although the sun is shining brightly.","position":2,"audioStartSeconds":5.089,"audioEndSeconds":9.849166666666667},{"speaker":"A","text":"If we go to the park now our sandwiches will definitely get covered in sand.","position":3,"audioStartSeconds":10.049166666666666,"audioEndSeconds":14.895333333333333},{"speaker":"B","text":"My brother told me that the local park is too windy for flying kites safely.","position":4,"audioStartSeconds":15.095333333333333,"audioEndSeconds":19.838375},{"speaker":"A","text":"We definitely need to change our outdoor plan because of this terrible weather.","position":5,"audioStartSeconds":20.038375,"audioEndSeconds":24.754875},{"speaker":"B","text":"What alternative indoor activity do you think we should try instead?","position":6,"audioStartSeconds":24.954875,"audioEndSeconds":29.349208333333333},{"speaker":"A","text":"We could visit the science museum because they have a brand new dinosaur exhibition.","position":7,"audioStartSeconds":29.549208333333333,"audioEndSeconds":34.72958333333333},{"speaker":"B","text":"That sounds fascinating although I would rather spend our afternoon at the art gallery.","position":8,"audioStartSeconds":34.92958333333333,"audioEndSeconds":40.045541666666665},{"speaker":"A","text":"The art gallery is quite crowded on Saturdays when admission is completely free.","position":9,"audioStartSeconds":40.24554166666667,"audioEndSeconds":45.567708333333336},{"speaker":"B","text":"You make a very good point about the crowds making it difficult to relax.","position":10,"audioStartSeconds":45.76770833333333,"audioEndSeconds":50.406875},{"speaker":"A","text":"Let us go to the science museum since it has large quiet rooms for families.","position":11,"audioStartSeconds":50.606875,"audioEndSeconds":55.632666666666665},{"speaker":"B","text":"That is a brilliant idea because we can also watch an educational movie there.","position":12,"audioStartSeconds":55.83266666666667,"audioEndSeconds":60.83266666666667},{"speaker":"A","text":"I will call our cousin to ask if he wants to join us there.","position":13,"audioStartSeconds":61.032666666666664,"audioEndSeconds":64.84708333333333},{"speaker":"B","text":"He will probably love the dinosaur bones since he studies biology at school.","position":14,"audioStartSeconds":65.04708333333333,"audioEndSeconds":70.072875},{"speaker":"A","text":"I am booking the tickets online right now so we can skip the long queues.","position":15,"audioStartSeconds":70.272875,"audioEndSeconds":75.13145833333333},{"speaker":"B","text":"I will gather our rain jackets while you finish securing the digital tickets.","position":16,"audioStartSeconds":75.33145833333333,"audioEndSeconds":80.14470833333333}],"questions":[{"prompt":"What is the main problem with the original picnic plan?","options":["The weather is too rainy for outdoor games.","The strong wind makes the park unsuitable.","The local park is completely closed today."],"answer":"B","evidenceSentence":5,"evidence":"We definitely need to change our outdoor plan because of this terrible weather","explanation":"Gió mạnh khiến việc đi dã ngoại ngoài công viên trở nên bất khả thi."},{"prompt":"Why does speaker A reject the idea of visiting the art gallery?","options":["It is too expensive to enter on weekends.","It becomes very crowded when admission is free.","It does not have any interesting exhibitions currently."],"answer":"B","evidenceSentence":9,"evidence":"The art gallery is quite crowded on Saturdays when admission is completely free","explanation":"Phòng trưng bày nghệ thuật rất đông đúc vào các ngày thứ bảy khi vé vào cửa miễn phí."},{"prompt":"What activity is available at the science museum according to speaker B?","options":["Watching an educational movie.","Building small wooden models.","Attending a painting workshop."],"answer":"A","evidenceSentence":12,"evidence":"That is a brilliant idea because we can also watch an educational movie there","explanation":"Bảo tàng khoa học có chiếu một bộ phim giáo dục mà họ có thể xem."},{"prompt":"Who does speaker A decide to invite to their new destination?","options":["Their neighbor.","Their cousin.","Their teacher."],"answer":"B","evidenceSentence":13,"evidence":"I will call our cousin to ask if he wants to join us there","explanation":"Speaker A quyết định gọi điện cho người anh em họ (cousin) để mời đi cùng."},{"prompt":"What subject does their relative study at school?","options":["Biology.","History.","Chemistry."],"answer":"A","evidenceSentence":14,"evidence":"He will probably love the dinosaur bones since he studies biology at school","explanation":"Người em họ học môn sinh học (biology) ở trường nên sẽ rất thích xương khủng long."},{"prompt":"What will speaker B do while speaker A books the tickets?","options":["Make some fresh sandwiches.","Gather their rain jackets.","Check the bus schedule."],"answer":"B","evidenceSentence":16,"evidence":"I will gather our rain jackets while you finish securing the digital tickets","explanation":"Speaker B sẽ thu gom áo khoác đi mưa trong lúc speaker A đặt vé trực tuyến."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
